def is_palindrome(s: str) -> bool:
    """True if s reads the same forwards and backwards, ignoring case and non-alphanumerics."""
    cleaned = [
        char.lower() for char in s
        if char.isalnum()
    ]
    return cleaned == cleaned[::-1]
```

